state = {"fetches": 0}
if os.path.exists(STATE):
    state = json.load(open(STATE))

req = urllib.request.Request(f"https://komarev.com/ghpvc/?username={USER}", headers={"User-Agent": "views-updater"})
svg = urllib.request.urlopen(req, timeout=30).read().decode()
nums = re.findall(r">\s*([\d,]+)\s*<", svg)
raw = int(nums[-1].replace(",", ""))
state["fetches"] += 1
views = max(raw - state["fetches"], 0)

txt = f"{views:,}".replace(",", " ")
paths, x = [], 0.0
for ch in txt:
    if ch == " ":
        x += 5
        continue
    d, w = DIGITS[ch]
    paths.append((d, x))
    x += w + 1
num_w = x - 1 if paths else 0
bw = num_w + 20
bx = 186 - bw
nx = bx + 10
num = "".join(f'<path d="{d}" fill="#F5F3FF" transform="translate({nx + off:.1f} 34.5)"/>' for d, off in paths)
out = TEMPLATE.replace("{BX}", f"{bx:.1f}").replace("{BW}", f"{bw:.1f}").replace("{NUM}", num)
open(OUT, "w", encoding="utf-8").write(out)
json.dump(state, open(STATE, "w"))
print("views:", views, "(raw", raw, "fetches", state["fetches"], ")")
